import fs from 'node:fs';import assert from 'node:assert/strict';import {hash,json} from './seal-simple-website-successor.mjs';
const stage='F:/VisibleMedicine/staging/20261024-toolbar-website',site=stage+'/website',prep=json(stage+'/PREPARATION.json'),native=json(prep.atlasReceipt),old=native.actualExportedModule,now=site+'/public/atlas-runtime/head-neck';
assert.equal(hash(prep.atlasReceipt),prep.atlasReceiptSha256);assert.equal(hash(old+'/manifest.json'),native.moduleManifestSha256);assert.equal(hash(native.browserResult),native.browserResultSha256);const a=json(old+'/manifest.json'),b=json(now+'/manifest.json');assert.equal(a.sourceCommit,prep.atlasHead);assert.equal(b.sourceCommit,prep.atlasHead);assert.deepEqual(b,a);
for(const row of a.files){assert.equal(hash(old+'/'+row.path),row.sha256);assert.equal(hash(now+'/'+row.path),row.sha256);assert.equal(fs.statSync(now+'/'+row.path).size,row.bytes);assert(fs.readFileSync(old+'/'+row.path).equals(fs.readFileSync(now+'/'+row.path)));}
fs.writeFileSync(stage+'/EXPORTED_BROWSER_IDENTITY.json',JSON.stringify({at:new Date().toISOString(),priorModule:old,currentModule:now,sourceCommit:prep.atlasHead,manifestSha256:native.moduleManifestSha256,files:a.files.length,allRuntimeBytesIdentical:true,originalBrowserResult:native.browserResult,originalBrowserResultSha256:native.browserResultSha256,newFullWebsiteBrowserReplay:false,authenticatedAcceptance:false,previewChanged:false},null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({source:prep.atlasHead,files:a.files.length,allRuntimeBytesIdentical:true,newWebsiteBrowserReplay:false}));
